   211→/// Take revenue from market reserves
   212→public(package) fun take_revenue<MarketType, CoinType>(
   213→    self: &mut Market<MarketType>,
   214→    amount: u64,
   215→    ctx: &mut TxContext,
   216→): Coin<CoinType> {
   217→    let reserve = self.reserves.load_mut_by_type(type_name::with_defining_ids<CoinType>());
   218→    let balance = reserve::take_revenue<MarketType, CoinType>(reserve, amount);
   219→    coin::from_balance(balance, ctx)
   220→}
   221→
   222→// ================== Internal Update Functions ================
   223→public(package) fun onboard_new_asset<MarketType, CoinType>(
   224→    self: &mut Market<MarketType>,
   225→    interest_model: InterestModel,
   226→    borrow: AssetConfig,
   227→    now: u64,
   228→    ctx: &mut TxContext,
   229→) {
   230→    assert!(!self.assets.supports<Asset<MarketType>, CoinType>(), error::asset_already_onboarded());
   231→
   232→    let new_asset = asset::new<MarketType>(interest_model, borrow, ctx);
   233→    self.assets.store<Asset<MarketType>, CoinType>(new_asset);
   234→
   235→    let reserve = reserve::new<MarketType, CoinType>(ctx, now);
   236→    self.reserves.store<Reserve<MarketType>, CoinType>(reserve);
   237→    
   238→    self.ema_spot_tolerance.store<Decimal, CoinType>(float::from_quotient(DEFAULT_EMA_SPOT_DIFF_TOLERANCE_BPS, DEFAULT_EMA_SPOT_DIFF_DENOMINATOR));
   239→
   240→    self.liquidity_miner.support_coin<MarketType, CoinType>(ctx);
   241→}
   242→
   243→public(package) fun handle_new_obligation<MarketType>(
   244→    self: &mut Market<MarketType>,
   245→    obligation: Obligation<MarketType>,
   246→) {
   247→    self.obligations.add(object::id(&obligation), obligation);
   248→}
   249→
   250→public(package) fun borrow_liquidity_mining<MarketType>(self: &Market<MarketType>): &LiquidityMiner<MarketType> {
   251→    &self.liquidity_miner
   252→}
   253→
   254→public(package) fun borrow_liquidity_mining_mut<MarketType>(self: &mut Market<MarketType>): &mut LiquidityMiner<MarketType> {
   255→    &mut self.liquidity_miner
   256→}
   257→
   258→public(package) fun handle_mint<MarketType, CoinType>(
   259→    self: &mut Market<MarketType>,
   260→    obligation: ID,
   261→    coin: Coin<CoinType>,
   262→    now: u64,
   263→): (u64, u64) {
   264→    assert!(coin.value() != 0, error::no_zero_amount());
   265→
   266→    let name = type_name::with_defining_ids<CoinType>();
   267→    let deposit_amount = coin.value();
   268→
   269→    let asset = self.assets.load_mut_by_type(name);
   270→    assert!(!asset.deposit_paused(), error::deposit_paused_for_asset());
   271→
   272→    let asset_config = asset.asset_config();
   273→
   274→    let reserve = accrue_interest<MarketType>(name, &mut self.reserves, asset_config, asset.interest_model(), now);
   275→
   276→    // technically should be in stable coin value, but keep it this way for now
   277→    assert!(
   278→        !reserve.deposit_limit_breached<MarketType>(
   279→            deposit_amount,
   280→            asset_config.max_deposit_amount(),
   281→        ),
   282→        error::market_deposit_limit_exceeded(),
   283→    );
   284→
   285→    let ctoken = reserve.mint_ctokens(coin);
   286→    let ctoken_amount = ctoken.value();
   287→
   288→    // now handle obligation related
   289→    let obligation = self.obligations.borrow_mut(obligation);
   290→    assert!(
   291→        obligation.market_id() == self.id.uid_as_inner(),
   292→        error::obligation_from_different_market(),
   293→    );
   294→    obligation.deposit_ctoken<MarketType, CoinType>(ctoken);
   295→
   296→    // update rate limit deposit 
   297→    let emode = self.emode_group_registry.borrow_mut_emode(obligation.emode_group(), type_name::with_defining_ids<CoinType>());
   298→    emode.borrow_mut_deposit_limiter().reduce_outflow(now, deposit_amount);
   299→
   300→    (ctoken_amount, obligation.ctoken_amount_by_coin(name))
   301→}
   302→
   303→public(package) fun handle_withdraw<MarketType, CoinType>(
   304→    self: &mut Market<MarketType>,
   305→    obligation_id: ID,
   306→    ctoken_amount: u64,
   307→    coin_decimals_registry: &CoinDecimalsRegistry,
   308→    x_oracle: &XOracle,
   309→    clock: &Clock,
   310→    now: u64,
   311→    ctx: &mut TxContext,
   312→): (Coin<CoinType>, u64) {
   313→    assert!(ctoken_amount != 0, error::no_zero_amount());
   314→
   315→    let name = type_name::with_defining_ids<CoinType>();
   316→
   317→    let asset = self.assets.load_by_type(name);
   318→    assert!(!asset.withdraw_paused(), error::withdraw_paused_for_asset());
   319→
   320→
   321→    let obligation = self.obligations.borrow_mut(obligation_id);
   322→    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());
   323→
   324→    // refresh all interest
   325→    let emode_group = self.emode_group_registry.borrow_emode_group_mut(obligation.emode_group());
   326→    refresh_obligation_assets_interest<MarketType>(&self.assets, emode_group, &mut self.reserves, obligation, now);
   327→
   328→    let ctoken = obligation.withdraw_ctokens(ctoken_amount);
   329→    let ctokens_left = obligation.ctoken_amount_by_coin(name);
   330→
   331→    // TODO: if the asset is not collateral, skip obligation safety check
   332→    let is_obligation_safe = is_obligation_safe(
   333→        self.emode_group_registry.borrow_emode_group(obligation.emode_group()),
   334→        &self.reserves,
   335→        &self.ema_spot_tolerance,
   336→
   337→        obligation,
   338→        coin_decimals_registry,
   339→        x_oracle,
   340→        clock,
   341→    );
   342→    assert!(is_obligation_safe, error::obligation_not_safe_after_operation());
   343→
   344→    let reserve = self.reserves.load_mut_by_type(name);
   345→    let deposit = reserve.burn_ctokens<MarketType, CoinType>(ctoken.into_coin(ctx));
   346→
   347→    // rate limit deposit withdraw
   348→    let emode = self.emode_group_registry.borrow_mut_emode(obligation.emode_group(), type_name::with_defining_ids<CoinType>());
   349→    emode.borrow_mut_deposit_limiter().add_outflow(
   350→        now,
   351→        deposit.value(),
   352→    );
   353→
   354→    // update adl
   355→
   356→    // use ceiling, slighly more 
   357→    let total_deposit = reserve.total_deposit_plus_interest().ceil();
   358→    let adl = dynamic_field::borrow_mut<ADLRegistryKey, AutoDeleverageRegistry>(&mut self.id, ADLRegistryKey {});
   359→    adl.try_stop_collateral_deleverage<CoinType>(type_name::with_defining_ids<MarketType>(), total_deposit);
   360→
   361→
   362→
   363→    (deposit.into_coin(ctx), ctokens_left)
   364→}
   365→
   366→public(package) fun handle_borrow<MarketType, CoinType>(
   367→    self: &mut Market<MarketType>,
   368→    obligation_id: ID,
   369→    borrow_amount: u64,
   370→    coin_decimals_registry: &CoinDecimalsRegistry,
   371→    x_oracle: &XOracle,
   372→    clock: &Clock,
   373→    now: u64,
   374→): (Balance<CoinType>, Decimal, Decimal) {
   375→    assert!(borrow_amount != 0, error::no_zero_amount());
   376→
   377→    let name = type_name::with_defining_ids<CoinType>();
   378→
   379→
   380→
   381→    // basic checks
   382→    let asset = self.assets.load_mut_by_type(name);
   383→    assert!(!asset.borrow_paused(), error::borrow_paused_for_asset());
   384→
   385→
   386→
   387→    // load data for later checks
   388→    let asset_config = asset.asset_config();
   389→    let min_borrow_amount = asset_config.min_borrow_amount();
   390→    let asset_max_borrow_amount = asset_config.max_borrow_amount();
   391→
   392→
   393→    let obligation = self
   394→        .obligations
   395→        .borrow_mut(obligation_id);
   396→    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());
   397→    let asset_name = type_name::with_defining_ids<CoinType>();
   398→
   399→    // make sure the outflow is rate limited
   400→    let emode = self.emode_group_registry.borrow_mut_emode(obligation.emode_group(), asset_name);
   401→    let emode_max_borrow_amount = emode.borrow().max_borrow_amount();
   402→    emode.borrow_mut_borrow_limiter().add_outflow(now, borrow_amount);
   403→
   404→    let obligation_old_total_borrow_amount = if (!obligation.has_debt(name)) { float::zero() } else { obligation.debt(name).unsafe_debt_amount() };
   405→
   406→    // refresh only borrow, practically, obligation owner can borrow a bit more due to collateral interest
   407→    refresh_obligation_borrow_interest_with_new_borrow<MarketType>(name, &self.assets, &mut self.reserves, obligation, now);
   408→
   409→    // update obligation
   410→    let borrow_index = self.reserves.load_by_type(name).borrow_index().value();
   411→
   412→    obligation.try_borrow_asset<MarketType, CoinType>(borrow_amount, borrow_index);
   413→    obligation.enforce_post_borrow_repay_invariant<MarketType, CoinType>(min_borrow_amount);
   414→
   415→    // interest updated, should be up to date
   416→    let obligation_new_total_borrow_amount = obligation.debt(name).unsafe_debt_amount();
   417→    let emode_group = self.emode_group_registry.borrow_emode_group_mut(obligation.emode_group());
   418→
   419→
   420→    // make sure the emode group borrow limit is not breached
   421→    let emode_group_total_borrow = emode_group.update_asset_borrow(name, obligation_old_total_borrow_amount, obligation_new_total_borrow_amount);
   422→    assert!(emode_group_total_borrow.le(math::float::from(emode_max_borrow_amount)), error::emode_borrow_limit_exceeded());
   423→
   424→    let is_obligation_safe = is_obligation_safe(
   425→        emode_group,
   426→        &self.reserves,
   427→        &self.ema_spot_tolerance,
   428→
   429→        self.obligations.borrow(obligation_id),
   430→        coin_decimals_registry,
   431→        x_oracle,
   432→        clock,
   433→    );
   434→    assert!(is_obligation_safe, error::obligation_not_safe_after_operation());
   435→
   436→    // perform borrow
   437→    let reserve = self.reserves.load_mut_by_type(name);
   438→    let balance = reserve.borrow_amount<MarketType, CoinType>(borrow_amount);
   439→
   440→    assert!((*reserve.debt()).ceil() <= asset_max_borrow_amount, error::market_borrow_limit_exceeded());
   441→
   442→    (balance, borrow_index, obligation_new_total_borrow_amount)
   443→}
