    15→public struct NewLimiter has store, drop, copy {
    16→    outflow_limit: u64,
    17→    outflow_cycle_duration: u32,
    18→    outflow_segment_duration: u32,
    19→}
    20→
    21→public struct Limiters has drop {}
    22→
    23→public struct Segment has drop, store {
    24→    index: u64,
    25→    value: u64,
    26→}
    27→
    28→public(package) fun new_from_struct(self: NewLimiter): Limiter {
    29→    Limiter {
