    31→        outflow_cycle_duration: self.outflow_cycle_duration,
    32→        outflow_segment_duration: self.outflow_segment_duration,
    33→        outflow_segments: build_segments(
    34→            self.outflow_cycle_duration,
    35→            self.outflow_segment_duration,
