    39→
    40→public(package) fun create_new_limiter_change(
    41→    outflow_limit: u64,
    42→    outflow_cycle_duration: u32,
    43→    outflow_segment_duration: u32,
    44→): NewLimiter {
    45→    validate_limiter_params(outflow_cycle_duration, outflow_segment_duration);
    46→    NewLimiter {
    47→        outflow_cycle_duration, outflow_segment_duration, outflow_limit
    48→    }
    49→}
    50→
    51→public(package) fun update_outflow_limit_params(
    52→    limiter: &mut Limiter,
    53→    new_limit: u64,
    54→) {
    55→    limiter.outflow_limit = new_limit;
    56→}
    57→
    58→/// updating outflow segment params will resets the segments values
    59→public(package) fun update_outflow_segment_params(
    60→    limiter: &mut Limiter,
    61→    cycle_duration: u32,
    62→    segment_duration: u32,
    63→) {
    64→    validate_limiter_params(cycle_duration, segment_duration);
    65→
    66→    limiter.outflow_segment_duration = segment_duration;
    67→    limiter.outflow_cycle_duration = cycle_duration;
    68→    limiter.outflow_segments =
    69→        build_segments(
    70→            cycle_duration,
    71→            segment_duration,
    72→        );
    73→}
    74→
    75→/// add_outflow will add the value of the outflow to the current segment
    76→/// but before adding it, there will be a check
    77→/// to validate that the outflow doesn't over the limit
    78→public(package) fun add_outflow(
    79→    limiter: &mut Limiter,
    80→    now: u64,
    81→    value: u64,
    82→) {
    83→    let curr_outflow = limiter.count_current_outflow(now);
    84→    assert!(curr_outflow + value <= limiter.outflow_limit, error::outflow_reach_limit_error());
    85→
    86→    let timestamp_index = now / (limiter.outflow_segment_duration as u64);
    87→    let curr_index = timestamp_index % vector::length(&limiter.outflow_segments);
    88→    let segment = vector::borrow_mut<Segment>(&mut limiter.outflow_segments, curr_index);
    89→    if (segment.index != timestamp_index) {
    90→        segment.index = timestamp_index;
    91→        segment.value = 0;
    92→    };
    93→    segment.value = segment.value + value;
    94→}
    95→
    96→/// reducing the outflow value of current segment
    97→/// that's mean the sum of all segments in one cycle is also reduced
    98→/// NOTE: keep in mind that reducing a HUGE number of outflow
    99→/// of current segment doesn't affect the total value of outflow in a cycle
   100→public(package) fun reduce_outflow(
   101→    limiter: &mut Limiter,
   102→    now: u64,
   103→    reduced_value: u64,
   104→) {
   105→
   106→    let timestamp_index = now / (limiter.outflow_segment_duration as u64);
   107→    let curr_index = timestamp_index % vector::length(&limiter.outflow_segments);
   108→    let segment = vector::borrow_mut<Segment>(&mut limiter.outflow_segments, curr_index);
   109→    if (segment.index != timestamp_index) {
   110→        segment.index = timestamp_index;
   111→        segment.value = 0;
   112→    };
   113→
   114→    if (segment.value <= reduced_value) {
   115→        segment.value = 0;
   116→    } else {
   117→        segment.value = segment.value - reduced_value;
   118→    }
   119→}
   120→
   121→/// return the sum of segments in one cycle
   122→public(package) fun current_usage(
   123→    limiter: &Limiter,
   124→    now: u64,
   125→): RateLimitUsage {
   126→    RateLimitUsage { limit: limiter.outflow_limit, usage: limiter.count_current_outflow(now) }
   127→}
   128→
   129→public struct RateLimitUsage has drop, copy {
   130→    limit: u64,
   131→    usage: u64,
   132→}
   133→
   134→fun build_segments(outflow_cycle_duration: u32, outflow_segment_duration: u32): vector<Segment> {
   135→    let mut vec_segments = vector::empty();
   136→
   137→    let (mut i, len) = (0, outflow_cycle_duration / outflow_segment_duration);
   138→    while (i < len) {
   139→        vector::push_back(
   140→            &mut vec_segments,
   141→            Segment {
   142→                index: (i as u64),
   143→                value: 0,
   144→            },
   145→        );
   146→
   147→        i = i + 1;
   148→    };
   149→
   150→    vec_segments
   151→}
   152→
   153→/// return the sum of segments in one cycle
   154→fun count_current_outflow(
   155→    limiter: &Limiter,
   156→    now: u64,
   157→): u64 {
   158→    let mut curr_outflow: u64 = 0;
   159→    let timestamp_index = now / (limiter.outflow_segment_duration as u64);
   160→
   161→    let (mut i, len) = (0, vector::length(&limiter.outflow_segments));
   162→    while (i < len) {
   163→        let segment = vector::borrow<Segment>(&limiter.outflow_segments, i);
   164→        if ((len > timestamp_index) || (segment.index >= (timestamp_index - len + 1))) {
   165→            curr_outflow = curr_outflow + segment.value;
   166→        };
   167→        i = i + 1;
   168→    };
   169→
   170→    curr_outflow
   171→}
   172→
   173→fun validate_limiter_params(
   174→    outflow_cycle_duration: u32,
   175→    outflow_segment_duration: u32,
   176→) {
   177→    assert!(outflow_segment_duration != 0, error::invalid_params_error());
