module protocol::limiter;

use protocol::error;

const MAX_SEGMENTS: u32 = 48;

public struct Limiter has drop, store {
    outflow_limit: u64,
    outflow_cycle_duration: u32,
    /// how long is one segment in seconds
    outflow_segment_duration: u32,
    outflow_segments: vector<Segment>,
}

public struct NewLimiter has store, drop, copy {
    outflow_limit: u64,
    outflow_cycle_duration: u32,
    outflow_segment_duration: u32,
}

public struct Limiters has drop {}

public struct Segment has drop, store {
    index: u64,
    value: u64,
}

public(package) fun new_from_struct(self: NewLimiter): Limiter {
    Limiter {
        outflow_limit: self.outflow_limit,
        outflow_cycle_duration: self.outflow_cycle_duration,
        outflow_segment_duration: self.outflow_segment_duration,
        outflow_segments: build_segments(
            self.outflow_cycle_duration,
            self.outflow_segment_duration,
        ),
    }
}

public(package) fun create_new_limiter_change(
    outflow_limit: u64,
    outflow_cycle_duration: u32,
    outflow_segment_duration: u32,
): NewLimiter {
    validate_limiter_params(outflow_cycle_duration, outflow_segment_duration);
    NewLimiter {
        outflow_cycle_duration, outflow_segment_duration, outflow_limit
    }
}

public(package) fun update_outflow_limit_params(
    limiter: &mut Limiter,
    new_limit: u64,
) {
    limiter.outflow_limit = new_limit;
}

/// updating outflow segment params will resets the segments values
public(package) fun update_outflow_segment_params(
    limiter: &mut Limiter,
    cycle_duration: u32,
    segment_duration: u32,
) {
    validate_limiter_params(cycle_duration, segment_duration);

    limiter.outflow_segment_duration = segment_duration;
    limiter.outflow_cycle_duration = cycle_duration;
    limiter.outflow_segments =
        build_segments(
            cycle_duration,
            segment_duration,
        );
}

/// add_outflow will add the value of the outflow to the current segment
/// but before adding it, there will be a check
/// to validate that the outflow doesn't over the limit
public(package) fun add_outflow(
    limiter: &mut Limiter,
    now: u64,
    value: u64,
) {
    let curr_outflow = limiter.count_current_outflow(now);
    assert!(curr_outflow + value <= limiter.outflow_limit, error::outflow_reach_limit_error());

    let timestamp_index = now / (limiter.outflow_segment_duration as u64);
    let curr_index = timestamp_index % vector::length(&limiter.outflow_segments);
    let segment = vector::borrow_mut<Segment>(&mut limiter.outflow_segments, curr_index);
    if (segment.index != timestamp_index) {
        segment.index = timestamp_index;
        segment.value = 0;
    };
    segment.value = segment.value + value;
}

/// reducing the outflow value of current segment
/// that's mean the sum of all segments in one cycle is also reduced
/// NOTE: keep in mind that reducing a HUGE number of outflow
/// of current segment doesn't affect the total value of outflow in a cycle
public(package) fun reduce_outflow(
    limiter: &mut Limiter,
    now: u64,
    reduced_value: u64,
) {

    let timestamp_index = now / (limiter.outflow_segment_duration as u64);
    let curr_index = timestamp_index % vector::length(&limiter.outflow_segments);
    let segment = vector::borrow_mut<Segment>(&mut limiter.outflow_segments, curr_index);
    if (segment.index != timestamp_index) {
        segment.index = timestamp_index;
        segment.value = 0;
    };

    if (segment.value <= reduced_value) {
        segment.value = 0;
    } else {
        segment.value = segment.value - reduced_value;
    }
}

/// return the sum of segments in one cycle
public(package) fun current_usage(
    limiter: &Limiter,
    now: u64,
): RateLimitUsage {
    RateLimitUsage { limit: limiter.outflow_limit, usage: limiter.count_current_outflow(now) }
}

public struct RateLimitUsage has drop, copy {
    limit: u64,
    usage: u64,
}

fun build_segments(outflow_cycle_duration: u32, outflow_segment_duration: u32): vector<Segment> {
    let mut vec_segments = vector::empty();

    let (mut i, len) = (0, outflow_cycle_duration / outflow_segment_duration);
    while (i < len) {
        vector::push_back(
            &mut vec_segments,
            Segment {
                index: (i as u64),
                value: 0,
            },
        );

        i = i + 1;
    };

    vec_segments
}

/// return the sum of segments in one cycle
fun count_current_outflow(
    limiter: &Limiter,
    now: u64,
): u64 {
    let mut curr_outflow: u64 = 0;
    let timestamp_index = now / (limiter.outflow_segment_duration as u64);

    let (mut i, len) = (0, vector::length(&limiter.outflow_segments));
    while (i < len) {
        let segment = vector::borrow<Segment>(&limiter.outflow_segments, i);
        if ((len > timestamp_index) || (segment.index >= (timestamp_index - len + 1))) {
            curr_outflow = curr_outflow + segment.value;
        };
        i = i + 1;
    };

    curr_outflow
}

fun validate_limiter_params(
    outflow_cycle_duration: u32,
    outflow_segment_duration: u32,
) {
    assert!(outflow_segment_duration != 0, error::invalid_params_error());
    assert!(outflow_cycle_duration >= outflow_segment_duration, error::invalid_params_error());
    assert!(outflow_cycle_duration % outflow_segment_duration == 0, error::invalid_params_error());
    assert!(outflow_cycle_duration / outflow_segment_duration <= MAX_SEGMENTS, error::invalid_params_error());
}

#[test_only]
public(package) fun limit(self: &RateLimitUsage): u64 {
    self.limit
}

#[test_only]
public(package) fun usage(self: &RateLimitUsage): u64 {
    self.usage
}

#[test]
fun outflow_limit_test() {
    let segment_duration: u64 = 60 * 30;
    let cycle_duration: u64 = 60 * 60 * 24;
    let segment_count = cycle_duration / segment_duration;

    let mut limiter = new_from_struct(create_new_limiter_change(
        segment_count * 100,
        (cycle_duration as u32),
        (segment_duration as u32),
    ));

    let mut mock_timestamp = 100;

    let mut i = 0;
    while (i < segment_count) {
        mock_timestamp = mock_timestamp + segment_duration;
        limiter.add_outflow(mock_timestamp, 100);
        i = i + 1;
    };

    // updating the timestamp here clearing the very first segment that we filled last time
    // hence the outflow limiter wouldn't throw an error because it satisfy the limit
    mock_timestamp = mock_timestamp + segment_duration;
    limiter.add_outflow(mock_timestamp, 100);
    limiter.reduce_outflow( mock_timestamp, 100);
    limiter.add_outflow(mock_timestamp, 100);
}

#[test]
fun update_outflow_params_test() {
    let segment_duration: u64 = 60 * 30;
    let cycle_duration: u64 = 60 * 60 * 24;

    let mut limiter = new_from_struct(create_new_limiter_change(
        10000,
        (cycle_duration as u32),
        (segment_duration as u32),
    ));

    let mut mock_timestamp = 1000;

    limiter.add_outflow(mock_timestamp, 5000);
    mock_timestamp = mock_timestamp + segment_duration;
    limiter.add_outflow(mock_timestamp, 3000);

    let new_cycle_duration: u64 = 60 * 24;
    let new_segment_duration: u64 = 60;
    // updating outflow segment params will resets segment params
    limiter.update_outflow_segment_params(
        (new_cycle_duration as u32),
        (new_segment_duration as u32),
    );

    mock_timestamp = mock_timestamp + new_segment_duration;
    limiter.add_outflow(mock_timestamp, 5000);
    mock_timestamp = mock_timestamp + new_segment_duration;
    limiter.add_outflow(mock_timestamp, 5000);

    limiter.update_outflow_limit_params(11000);
    mock_timestamp = mock_timestamp + new_segment_duration;
    limiter.add_outflow(mock_timestamp, 1000);
}

#[test, expected_failure(abort_code = 105, location = protocol::limiter)]
fun outflow_limit_test_failed_reached_limit() {
    let segment_duration: u64 = 60 * 30;
    let cycle_duration: u64 = 60 * 60 * 24;

    let mut limiter = new_from_struct(create_new_limiter_change(
        10000,
        (cycle_duration as u32),
        (segment_duration as u32),
    ));
    let mut mock_timestamp = 1000;

    limiter.add_outflow(mock_timestamp, 5000);
    mock_timestamp = mock_timestamp + segment_duration;
    limiter.add_outflow(mock_timestamp, 3000);
    mock_timestamp = mock_timestamp + segment_duration;
    limiter.add_outflow(mock_timestamp, 2001);
}

