    oracle_base_token: BaseToken,

    collateral_factor: Decimal,
    liquidation_factor: Decimal,
    liquidation_incentive: Decimal,

    max_borrow_amount: u64,
    borrow_weight: Decimal,

    flash_loan_fee_rate: Decimal,

    deposit_limiter: RateLimitUsage,
    borrow_limiter: RateLimitUsage,
}

public(package) fun ensure_group_exists(self: &EModeGroupRegistry, group: u8) {
    assert!(self.groups.contains(group), error::emode_group_not_exists());
}

public fun list_assets(registry: &EModeGroupRegistry, group: u8, now: u64): vector<EModeInfo> {
    registry.ensure_group_exists(group);

    let group = registry.groups.borrow(group);

    let oracle_base_token = group.get_oracle_base_token();
    let assets = group.assets.keys();

    let (mut i, n) = (0, assets.length());

    let mut results = vector::empty<EModeInfo>();
    while (i < n) {
        let emode = group.assets.load_by_type(*assets.borrow(i));
        let (deposit_limiter, borrow_limiter) = emode.limiter_usage(now);

        results.push_back(
            EModeInfo {
                asset: *assets.borrow(i),
                oracle_base_token,
                collateral_factor: emode.collateral().collateral_factor(),
                liquidation_factor: emode.collateral().liquidation_factor(),
                liquidation_incentive: emode.collateral().liquidation_incentive(),
                max_borrow_amount: emode.borrow().max_borrow_amount(),
                borrow_weight: emode.borrow().borrow_weight(),
                flash_loan_fee_rate: emode.flash_loan().fee_rate(),
                deposit_limiter,
                borrow_limiter,
            }
        );
        i = i + 1;
    };

    results
}

public(package) fun borrow_emode_group(registry: &EModeGroupRegistry, group: u8): &EModeGroup {
    registry.ensure_group_exists(group);
    registry.groups.borrow(group)
}

public(package) fun borrow_emode(self: &EModeGroup, asset: TypeName): &EMode {
    assert!(self.assets.supports_type(asset), error::emode_group_does_not_support_asset());
    self.assets.load_by_type(asset)
}

public(package) fun borrow_emode_mut(self: &mut EModeGroup, asset: TypeName): &mut EMode {
    assert!(self.assets.supports_type(asset), error::emode_group_does_not_support_asset());
    self.assets.load_mut_by_type(asset)
}

public(package) fun collateral(self: &EMode): &EModeCollateral { dynamic_field::borrow<DFKey<EModeCollateral>, EModeCollateral>(&self.id, DFKey<EModeCollateral> {}) }
public(package) fun collateral_factor(self: &EModeCollateral): Decimal { self.collateral_factor }
public(package) fun liquidation_factor(self: &EModeCollateral): Decimal { self.liquidation_factor }
public(package) fun liquidation_incentive(self: &EModeCollateral): Decimal { self.liquidation_incentive }
public(package) fun borrow(self: &EMode): &EModeBorrow { dynamic_field::borrow<DFKey<EModeBorrow>, EModeBorrow>(&self.id, DFKey<EModeBorrow> {}) }
public(package) fun max_borrow_amount(self: &EModeBorrow): u64 { self.max_borrow_amount }
public(package) fun borrow_weight(self: &EModeBorrow): Decimal { self.borrow_weight }
public(package) fun flash_loan(self: &EMode): &EModeFlashLoan { dynamic_field::borrow<DFKey<EModeFlashLoan>, EModeFlashLoan>(&self.id, DFKey<EModeFlashLoan> {}) }
public(package) fun fee_rate(self: &EModeFlashLoan): Decimal { self.flash_loan_fee_rate }

public(package) fun limiter_usage(self: &EMode, now: u64): (RateLimitUsage, RateLimitUsage) {
    let limiter = dynamic_field::borrow<DFKey<EModeRateLimiter>, EModeRateLimiter>(&self.id, DFKey<EModeRateLimiter> {});
    (limiter.deposit.current_usage(now), limiter.borrow.current_usage(now))
}

/// @title Module for flash loan from base asset pools
module protocol::flash_loan;

use std::type_name::{Self, TypeName};
use std::string::String;

use sui::coin::Coin;
use sui::clock::Clock;

use sui::event::emit;

use x_oracle::x_oracle::XOracle;
use x_oracle::user_oracle::get_price;

use protocol::app::{ProtocolApp, PackageCallerCap};
use protocol::coin_decimals_registry::CoinDecimalsRegistry;
use protocol::market::{Market, FlashLoan};
use protocol::value::coin_value;

public struct BorrowFlashLoanEvent has copy, drop {
    market: TypeName,
    borrower: address,
    asset: TypeName,
    amount: u64,
    fee: u64,
}

public struct RepayFlashLoanEvent has copy, drop {
    market: TypeName,
    borrower: address,
    asset: TypeName,
    amount: u64,
    fee: u64,
}

public fun borrow_flash_loan<MarketType, CoinType>(
    app: &ProtocolApp,
    cap: &PackageCallerCap,

    market: &mut Market<MarketType>,

    emode_group: u8,
    amount: u64,

    ctx: &mut TxContext,
): (Coin<CoinType>, FlashLoan<MarketType, CoinType>) {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    app.ensure_has_permission(object::id(cap), protocol::whitelist_admin::flash_loan());

    borrow_flash_loan_inner<MarketType, CoinType>(market, amount, emode_group, ctx)
}

/// @notice Repay flash loan to market
/// @dev This is the only method to repay flash loan, consume the flash loan hot potato object
/// @param version The version control object, contract version must match with this
/// @param market The market object, it contains base assets, and related protocol configs
/// @param coin The coin object to repay
/// @param loan The flash loan hot potato object, which contains the borrowed amount and fee
/// @ctx The SUI transaction context object
/// @custom:T The type of asset to repay
public fun repay_flash_loan<MarketType, CoinType>(
    app: &mut ProtocolApp,
    market: &mut Market<MarketType>,

    coin: Coin<CoinType>,
    loan: FlashLoan<MarketType, CoinType>,

    ctx: &mut TxContext,
) {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    // Emit the repay flash loan event
    emit(RepayFlashLoanEvent {
        market: type_name::with_defining_ids<MarketType>(),
        borrower: ctx.sender(),
        asset: type_name::with_defining_ids<CoinType>(),
        // amount is total repay coin amount
        amount: coin.value(),
        fee: loan.fee(),
    });

    let referral = app.referral_mut();
    // Put the asset back to the market and consume the flash loan hot potato object
    market.repay_flash_loan(coin, loan, referral, std::option::none(), ctx);
}

public fun repay_flash_loan_increase_referral_qualification<MarketType, CoinType>(
    app: &mut ProtocolApp,
    market: &mut Market<MarketType>,

    coin: Coin<CoinType>,
    loan: FlashLoan<MarketType, CoinType>,

    maybe_referral_code: Option<String>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,

    ctx: &mut TxContext,
) {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    // Emit the repay flash loan event
    emit(RepayFlashLoanEvent {
        market: type_name::with_defining_ids<MarketType>(),
        borrower: ctx.sender(),
        asset: type_name::with_defining_ids<CoinType>(),
        // amount is total repay coin amount
        amount: coin.value(),
        fee: loan.fee(),
    });

    let referral = app.referral_mut();
    track_referral(referral, ctx.sender(), loan.loan_amount(), type_name::with_defining_ids<CoinType>(), coin_decimals_registry, x_oracle, clock);
    let maybe_referral_code = referral.try_map_referral_code(ctx.sender(), maybe_referral_code);

    // Put the asset back to the market and consume the flash loan hot potato object
    market.repay_flash_loan(coin, loan, referral, maybe_referral_code, ctx);
}

fun borrow_flash_loan_inner<MarketType, CoinType>(
    market: &mut Market<MarketType>,
    amount: u64,
    emode_group: u8,
    ctx: &mut TxContext,
): (Coin<CoinType>, FlashLoan<MarketType, CoinType>) {
    assert!(!market.has_circuit_break_triggered(), protocol::error::market_under_circuit_break());

    let (coin, flash_loan) = market.borrow_flash_loan(emode_group, amount, ctx);

    // Emit the borrow flash loan event
    emit(BorrowFlashLoanEvent {
        market: type_name::with_defining_ids<MarketType>(),
        borrower: ctx.sender(),
        asset: type_name::with_defining_ids<CoinType>(),
        fee: flash_loan.fee(),
        amount,
    });

    // Return the borrowed coin object and the flash loan hot potato object
    (coin, flash_loan)
}

fun track_referral(
    referral: &mut protocol::referral::Referral,

    who: address,

    token_amount: u64,
    token_type: TypeName,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
) {
    if (referral.is_qualified_to_create_referral_code(who)) return;

    let decimals = coin_decimals_registry.decimals(token_type);
    // always use usd price
    let usd_price = get_price(x_oracle, token_type, x_oracle::x_oracle::usd(), clock);
    let collateral_value_usd = coin_value(usd_price, math::float::from(token_amount), decimals);

    referral.increase_usd_qualification(who, collateral_value_usd.floor());
}

#[test_only]
public fun borrow_flash_loan_against_group<MarketType, CoinType>(
    market: &mut Market<MarketType>,
    amount: u64,
    emode_group: u8,
    ctx: &mut TxContext,
): (Coin<CoinType>, FlashLoan<MarketType, CoinType>) {
    borrow_flash_loan_inner<MarketType, CoinType>(market, amount, emode_group, ctx)
}

/// @title Module for handling the liquidation request
/// @notice adopts soft liquidation. Liquidation amount should be no bigger than the amount that would drecrease the risk level of obligation to 1.
module protocol::liquidate;

use protocol::coin_decimals_registry::CoinDecimalsRegistry;
use protocol::market::Market;
use std::type_name::{Self, TypeName};
use sui::clock::{Self, Clock};
use sui::coin::Coin;
use sui::event::emit;
use x_oracle::user_oracle::get_price;
use x_oracle::x_oracle::XOracle;
use math::float::Decimal;
use protocol::liquidity_miner::{get_borrow_reward_type, get_deposit_reward_type};
use protocol::app::{ProtocolApp, PackageCallerCap};

public enum LiquidationType has copy, drop{
    NormalLiquidation,
    ADLBorrow,
    ADLCollateral,
}

public struct LiquidateEvent has copy, drop {
    liquidator: address,
    liquidation_type: LiquidationType,

    market: TypeName,
    obligation: ID,


    collateral_price: Decimal,
    debt_price: Decimal,

    collateral_type: TypeName,
    seized_ctoken_amount: u64,
    seized_collateral_amount: u64,
    ctokens_remaining: u64,

    debt_type: TypeName,
    total_borrow_remaining: Decimal,
    borrow_index: Decimal,
    repay_amount: u64,
    refund_amount: u64,

    timestamp: u64,
}

fun pre_liquidation_check<MarketType>(
    app: &ProtocolApp,
    cap: &PackageCallerCap,
    market: &Market<MarketType>,
    permission: u8,
) {
    app.validate_market<MarketType>(market);
    app.ensure_version_matches();

    app.ensure_has_permission(object::id(cap), permission);

    assert!(!market.has_circuit_break_triggered(), protocol::error::market_under_circuit_break());
}

fun post_liquidation<MarketType, DebtType, CollateralType>(
    now: u64,
    repay_amount: u64,
    refund_amount: u64,
    liquidation_type: LiquidationType,

    obligation_id: ID,
    market: &mut Market<MarketType>,

    collateral_amount: u64,
    ctoken_amount: u64,

    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &TxContext,
) {
    let debt_type = type_name::with_defining_ids<DebtType>();
    let collateral_type = type_name::with_defining_ids<CollateralType>();

    let obligation = market.borrow_obligation(obligation_id);
    let oracle = market.emode_registry().borrow_emode_group(obligation.emode_group()).get_oracle_base_token();

    let total_ctoken_amount = obligation.ctoken_amount_by_coin(collateral_type);
    let (total_borrow, borrow_index) = if (obligation.has_debt(debt_type)) {
        let debt = obligation.debt(debt_type);
        (debt.unsafe_debt_amount(), *debt.borrow_index())
    }  else {
        (math::float::zero(), math::float::one())
    };

    let miner = market.borrow_liquidity_mining_mut<MarketType>();
    miner.update_obligation_reward_manager<MarketType, DebtType>(
        get_borrow_reward_type(),
        obligation_id,
        total_borrow.floor(),
        clock
    );
    miner.update_obligation_reward_manager<MarketType, CollateralType>(
        get_deposit_reward_type(),
        obligation_id,
        total_ctoken_amount,
        clock
    );

    emit(LiquidateEvent {
        liquidator: ctx.sender(),
        liquidation_type,

        market: type_name::with_defining_ids<MarketType>(),
        obligation: obligation_id,

        debt_type,
        collateral_type,

        collateral_price: get_price(x_oracle, type_name::with_defining_ids<CollateralType>(), oracle, clock),
        debt_price: get_price(x_oracle, type_name::with_defining_ids<DebtType>(), oracle, clock),

        seized_ctoken_amount: ctoken_amount,
        seized_collateral_amount: collateral_amount,
        ctokens_remaining: total_ctoken_amount,

        total_borrow_remaining: total_borrow,
        borrow_index,
        repay_amount,
        refund_amount,

        timestamp: now,
    });
}

#[allow(lint(self_transfer))]
public fun liquidate<MarketType, DebtType, CollateralType>(
    app: &ProtocolApp,
    cap: &PackageCallerCap,

    obligation_id: ID,
    market: &mut Market<MarketType>,

    available_repay_coin: Coin<DebtType>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
) {
    let (collateral_balance, refund) = liquidate_as_coin<MarketType, DebtType, CollateralType>(
        app,
        cap,
        obligation_id, 
        market, 
        available_repay_coin, 
        coin_decimals_registry, 
        x_oracle, 
        clock, 
        ctx
    );
    // Transfer the liquiated collateral to the sender
    transfer::public_transfer(collateral_balance, ctx.sender());
    transfer::public_transfer(refund, ctx.sender());
}

public fun liquidate_as_coin<MarketType, DebtType, CollateralType>(
    app: &ProtocolApp,
    cap: &PackageCallerCap,

    obligation_id: ID,
    market: &mut Market<MarketType>,

    available_repay_coin: Coin<DebtType>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
): (Coin<CollateralType>, Coin<DebtType>) {
    pre_liquidation_check<MarketType>(app, cap, market, protocol::whitelist_admin::liquidation());

    let now = clock::timestamp_ms(clock) / 1000;
    let repay_amount = available_repay_coin.value();

    let (collateral_balance, refund, ctoken_amount) = market.handle_liquidation<MarketType, DebtType, CollateralType>(
        obligation_id,
        available_repay_coin,
        coin_decimals_registry,
        x_oracle,
        clock,
        now,
        ctx,
    );

    post_liquidation<MarketType, DebtType, CollateralType>(
        now, 
        repay_amount,
        refund.value(),
        LiquidationType::NormalLiquidation, 
        obligation_id, 
        market, 
        collateral_balance.value(),
        ctoken_amount, 
        x_oracle, 
        clock, 
        ctx
    );

    (collateral_balance, refund)
}

